//_write ​函数​在​ syscalls.c ​中​， ​使用​ __weak ​定义​， ​所以​可以​直接​在​其他​文件​中​定义​ _write ​函数​
__attribute__((weak)) int _write(int file, char *ptr, int len)
{
    int DataIdx;
    for (DataIdx = 0; DataIdx &lt; len; DataIdx++)
    {
          while ((USART1-&gt;SR &amp; 0X40) == 0); //​等待​发送​完毕​
          USART1-&gt;DR = (uint8_t) *ptr++;
    }
    return len;
}

/* USER CODE END 1 */
